export const OUTPUT_REPAIR_PENDING = "output-journal-repair-pending.json";
export const OUTPUT_BACKUP_MANIFEST = "output-journal-backup.json";
export const OUTPUT_ANCHOR = "output-journal.jsonl";
export const OUTPUT_HEAD = "output-journal-head.json";
export const OUTPUT_SEGMENTS = "output-journal-segments.json";
export const MAX_OUTPUT_REPAIR_BYTES = 512 * 1024 * 1024;

export interface BackupFile extends FileIdentity {
  name: string;
  bytes: number;
  sha256: string;
}
export interface OutputJournalBackupManifest {
  format: "codeshell-output-journal-backup";
  version: 1;
  authority: RepairAuthority;
  floor: OutputPosition;
  files: BackupFile[];
}
export interface RepairSegment extends FileIdentity {
  name: string;
  start: OutputPosition;
  end?: OutputPosition;
}
export interface RepairStorageManifest {
  version: 1;
  identity: string;
  origin: OutputPosition;
  floor: OutputPosition;
  anchor: { end: OutputPosition; retained: boolean };
  segments: RepairSegment[];
}

export class OutputJournalRepairError extends Error {
  constructor(
    readonly code: string,
    message: string,
    options?: ErrorOptions,
  ) {
    super(message, options);
    this.name = "OutputJournalRepairError";
  }
}
export function requireRepair(value: unknown, code: string, message: string): asserts value {
  if (!value) throw new OutputJournalRepairError(code, message);
}

export function validPosition(value: OutputPosition): boolean {
  return Boolean(
    value &&
    Number.isSafeInteger(value.sequence) &&
    value.sequence >= 0 &&
    Number.isSafeInteger(value.offset) &&
    value.offset >= 0 &&
    /^[a-f0-9]{64}$/.test(value.hash),
  );
}
export function decodeJson(data: Buffer): any {
  return JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(data));
}
export function segmentBarrier(identity: string): Buffer {
  return Buffer.from(
    JSON.stringify({ storage: "codeshell-output-segments", version: 1, identity }) + "\n",
  );
}

let expected = manifest.anchor.retained ? manifest.anchor.end : manifest.floor;
const seen = new Set<string>();
for (let index = 0; index < manifest.segments.length; index++) {
  const segment = manifest.segments[index]!;
  requireRepair(
    /^output-segment-[a-f0-9-]{36}\.jsonl$/.test(segment.name) &&
      !seen.has(segment.name) &&
      validIdentity(segment) &&
      validPosition(segment.start) &&
      samePosition(segment.start, expected) &&
      (index === manifest.segments.length - 1
        ? segment.end === undefined
        : validPosition(segment.end!) &&
          segment.end!.sequence >= segment.start.sequence &&
          segment.end!.offset >= segment.start.offset),
    "manifest_unproved",
    "Segment manifest continuity is damaged",
  );
  seen.add(segment.name);
  if (segment.end) expected = segment.end;
}

export function encodeRepairStorage(manifest: RepairStorageManifest): Buffer {
  const data = Buffer.from(JSON.stringify({ manifest, sha256: sha256(JSON.stringify(manifest)) }));
  requireRepair(data.length <= 32768, "manifest_unproved", "Segment manifest exceeds its bound");
  const result = Buffer.alloc(32768, 0x20);
  data.copy(result);
  return result;
}
export function logicalStorage(manifest: RepairStorageManifest): string {
  return JSON.stringify({
    ...manifest,
    segments: manifest.segments.map(({ dev: _dev, ino: _ino, ...s }) => s),
  });
}

const entries = new Map(manifest.files.map((file) => [file.name, file]));
requireRepair(entries.size === manifest.files.length, "bundle_invalid", "Duplicate backup file");
const anchor = entries.get(OUTPUT_ANCHOR);

const start = { sequence: 0, offset: newline + 1, hash: authority.identityPin };
const regions: { name: string; base: number; from: number; to: number; end?: OutputPosition }[] =
  [];
let storage: RepairStorageManifest | undefined;

let bytes = Buffer.alloc(0);
read(OUTPUT_SEGMENTS, 0, item.bytes, (chunk) => {
  bytes = Buffer.concat([bytes, chunk]);
});
storage = parseRepairStorage(bytes, authority);

  regions.push({
    name: OUTPUT_ANCHOR,
    base: 0,
    from: start.offset,
    to: storage.anchor.end.offset,
    end: storage.anchor.end,
  });
}
for (const segment of storage.segments) {
  const item = entries.get(segment.name);
  requireRepair(

        item.bytes <= 32 * 1024 * 1024 &&
        (!segment.end || item.bytes === segment.end.offset - segment.start.offset),
      "bundle_invalid",
      "Backup segment is missing or incomplete",
    );
    regions.push({
      name: segment.name,
      base: segment.start.offset,
      from: 0,
      to: item.bytes,
      end: segment.end,
    });
  }
} else {
  requireRepair(
    samePosition(manifest.floor, start) && anchor.bytes === authority.head.offset,
    "bundle_invalid",
    "Single-file backup includes an unpublished tail or a gap",
  );
  regions.push({ name: OUTPUT_ANCHOR, base: 0, from: start.offset, to: anchor.bytes });
}
const expectedNames = [
  "state.json",
  OUTPUT_ANCHOR,
  OUTPUT_HEAD,
  ...(storage ? [OUTPUT_SEGMENTS, ...storage.segments.map((s) => s.name)] : []),
].sort();
requireRepair(
  [...entries.keys()].sort().join() === expectedNames.join(),
  "bundle_invalid",
  "Backup inventory is incomplete or ambiguous",
);
let current: OutputPosition = manifest.floor;

let fragment: { id: string; index: number; total: number } | undefined;
for (const region of regions) {
  let pending = Buffer.alloc(0),
    physical = region.from;
  read(region.name, region.from, region.to, (chunk) => {
    pending = Buffer.concat([pending, chunk]);
    for (;;) {
      const end = pending.indexOf(10);
      if (end < 0) break;
      requireRepair(end <= 256 * 1024, "chain_invalid", "Backup record exceeds its bound");
      const stored = decodeJson(pending.subarray(0, end)),
        { hash, ...value } = stored;
      const producer = value.producer;
      const validProducer =
        producer &&
        ["protocol", "host"].includes(producer.kind) &&
        typeof producer.id === "string" &&
        /^[A-Za-z0-9_-][A-Za-z0-9_.-]{0,127}$/.test(producer.id);
      requireRepair(
        value.sequence === current.sequence + 1 &&
          value.previousHash === current.hash &&
          hash === sha256(JSON.stringify(value)) &&
          !!value.event !== !!value.fragment &&
          ((value.version === undefined &&
            !value.run &&
            ((typeof value.runId === "string" && !producer) ||
              (value.runId === undefined && validProducer))) ||
            (value.version === 2 &&
              value.runId === undefined &&
              ((typeof value.run?.id === "string" && !!value.run.id && !producer) ||
                (!value.run && validProducer)))),
        "chain_invalid",
        "Backup record continuity failed",
      );
      if (value.event)
        requireRepair(
          typeof value.event === "object" && typeof value.event.type === "string" && !fragment,
          "chain_invalid",
          "Backup whole event interrupted a fragment group",
        );
      const part = value.fragment;
      if (part) {
        requireRepair(
          typeof part.id === "string" &&
            Number.isSafeInteger(part.index) &&
            Number.isSafeInteger(part.total) &&
            part.total >= 2 &&
            part.total <= 256 &&
            part.index >= 0 &&
            part.index < part.total &&
            typeof part.data === "string" &&
            part.data.length <= Math.ceil(65536 / 3) * 4 &&
            (fragment
              ? part.id === fragment.id &&
                part.total === fragment.total &&
                part.index === fragment.index + 1
              : part.index === 0),
          "chain_invalid",
          "Backup fragment continuity failed",
        );
        fragment = part.index === part.total - 1 ? undefined : part;
      }
      physical += end + 1;
      current = { sequence: value.sequence, offset: region.base + physical, hash };
      pending = pending.subarray(end + 1);
    }
    requireRepair(
      pending.length <= 256 * 1024,
      "chain_invalid",
      "Backup record exceeds its bound",
    );
  });
  requireRepair(
    pending.length === 0 && !fragment && (!region.end || samePosition(current, region.end)),
    "chain_invalid",
    "Backup segment is not a complete event boundary",
  );
}

requireRepair(
  fs.readdirSync(dir).sort().join() ===
    [OUTPUT_BACKUP_MANIFEST, ...manifest.files.map((f) => f.name)].sort().join(),
  "bundle_invalid",
  "Backup contains unexpected or missing files",
);

const checked = verifyBackupChain(manifest, (name, start, end, consume) =>
  readRange(fds.get(name)!, start, end, consume),
);
return { directory: dir, manifest, digest: sha256(text), fds, storage: checked.storage };

  files: BackupFile[] = [];
let total = 0;
for (const name of inventory(storage)) {
  const source = openFile(join(at.directory, name));
  try {
    const item = copyFile(source, join(target, name), name);
    total += item.bytes;
    files.push(item);
  } finally {
    fs.closeSync(source);
  }
  requireRepair(
    total <= MAX_OUTPUT_REPAIR_BYTES,
    "file_budget",
    "Backup exceeds its total bound",
  );

const manifest: OutputJournalBackupManifest = {
  format: "codeshell-output-journal-backup",
  version: 1,
  authority: at.authority,
  floor,
  files,
};
writePrivate(
  join(target, OUTPUT_BACKUP_MANIFEST),
  Buffer.from(JSON.stringify(manifest) + "\n"),
);

const data = encodeRepairStorage(updated);
writeAll(fd, data, 0);
fs.ftruncateSync(fd, data.length);
fs.fsyncSync(fd);

const MAX_JOURNAL_BYTES = 128 * 1024 * 1024;
const MAX_RECORD_BYTES = 256 * 1024;
const MAX_EVENT_BYTES = 16 * 1024 * 1024;
const CHUNK_BYTES = 64 * 1024;

interface RecordValue {
  version?: 2;
  sequence: number;
  runId?: string;
  run?: { id: string };
  producer?: OutputJournalProducer;
  event?: StreamEvent;
  fragment?: Fragment;
  previousHash: string;
}

append(event: StreamEvent): string {
  return this.appendBatch([event])[0];
}
/** All cursors become publishable only after the entire batch and head are durable. */
appendBatch(events: readonly StreamEvent[]): string[] {
  if (!events.length || events.length > 64) throw new Error("Invalid output batch bound");
  const values: Array<Pick<RecordValue, "event" | "fragment"> & { eventEnd: boolean }> = [];
  let bytes = 0;
  for (const event of events) {
    const serialized = JSON.stringify({
      ...event,
      outputCursor: undefined,
      outputRecovery: undefined,
    });
    const data = Buffer.from(serialized);
    bytes += data.length;
    if (data.length > MAX_EVENT_BYTES)
      throw new JournalError("incomplete", "Output event exceeds the 16 MiB recovery bound");
    if (events.length > 1 && bytes > 256 * 1024)
      throw new JournalError("incomplete", "Output batch exceeds its 256 KiB recovery bound");
    if (data.length <= CHUNK_BYTES)
      values.push({ event: JSON.parse(serialized), eventEnd: true });
    else {
      const id = randomUUID();
      const total = Math.ceil(data.length / CHUNK_BYTES);
      for (let index = 0; index < total; index++)
        values.push({
          fragment: {
            id,
            index,
            total,
            data: data
              .subarray(index * CHUNK_BYTES, (index + 1) * CHUNK_BYTES)
              .toString("base64"),
          },
          eventEnd: index === total - 1,
        });
    }
  }

let next = this.position;
const linesToWrite: string[] = [];
const cursors: string[] = [];
for (const { eventEnd, ...payload } of values) {
  const value: RecordValue = {
    version: 2,
    sequence: next.sequence + 1,
    ...(typeof this.owner === "string"
      ? { run: { id: this.owner } }
      : { producer: this.owner }),
    ...payload,
    previousHash: next.hash,
  };
  const hash = digest(JSON.stringify(value));
  const line = JSON.stringify({ ...value, hash }) + "\n";
  next = { sequence: value.sequence, offset: next.offset + Buffer.byteLength(line), hash };
  linesToWrite.push(line);
  if (eventEnd) cursors.push(token(this.identity, next));
}
const nextBytes = next.offset - this.position.offset;

let target = fd,
  offset = this.position.offset;
if (storage) {
  const active = storage.active();
  activeFd = target = active.fd;
  offset -= active.start.offset;
}
this.write(target, linesToWrite.join(""), offset);

export {
  backupOutputJournal,
  restoreOutputJournalBackup,
  inspectOutputJournalRepair,
} from "./output-journal-manual-repair.js";

test("explicit full backup repairs damaged bytes on the same anchor inode and the actual Web consumer preserves old cursors", () => {
  const f = fixture(),
    inode = fs.statSync(f.file).ino,
    original = fs.readFileSync(f.file);
  const snapshot = backupOutputJournal(f.root, f.id, f.backup);
  expect(snapshot.through).toBe(f.through);
  const damaged = corrupt(f.file);
  expect(readOutputJournal(f.root, f.id).complete).toBe(false);
  const repaired = restoreOutputJournalBackup(f.root, f.id, f.backup);
  expect(repaired.coverage).toBe("ok");
  expect(fs.statSync(f.file).ino).toBe(inode);
  expect(fs.readFileSync(f.file)).toEqual(original);
  expect(readOutputJournal(f.root, f.id, { after: f.first, through: f.through }).through).toBe(
    f.through,
  );
  const receipt = JSON.parse(
    fs.readFileSync(join(repaired.evidenceDirectory, "receipt.json"), "utf8"),
  ).value;
  const source = receipt.files.find((x: any) => x.name === "output-journal.jsonl");
  expect(source.sha256).toBe(hash(damaged));
  expect(fs.readFileSync(join(repaired.evidenceDirectory, "source/output-journal.jsonl"))).toEqual(
    damaged,
  );
  const events = fold(f);
  expect(events.map((event) => event.text)).toEqual(["first published body", f.large]);
  const restarted = new SessionOutputJournal(f.root, f.id, "fixture-run");
  const next = restarted.append({ type: "text_delta", text: "after repair" });
  expect(readOutputJournal(f.root, f.id, { after: f.through, through: next }).complete).toBe(true);
});

test("segmented corruption and a truly missing retained segment recover with durable physical-pin receipts and unchanged cursors", () => {
  const f = fixture();
  segment(f);
  f.writer.append({ type: "text_delta", text: "retained segment output" });
  const current = manifest(f),
    name = current.segments[0].name,
    old = fs.statSync(join(f.directory, name)).ino;
  const through = readOutputJournal(f.root, f.id).through;
  backupOutputJournal(f.root, f.id, f.backup);
  const anchorInode = fs.statSync(f.file).ino,
    manifestInode = fs.statSync(join(f.directory, "output-journal-segments.json")).ino;
  fs.unlinkSync(join(f.directory, name));
  expect(readOutputJournal(f.root, f.id).complete).toBe(false);
  const repaired = restoreOutputJournalBackup(f.root, f.id, f.backup);
  expect(manifest(f).segments[0].ino).not.toBe(old);
  expect(fs.statSync(f.file).ino).toBe(anchorInode);
  expect(fs.statSync(join(f.directory, "output-journal-segments.json")).ino).toBe(manifestInode);
  expect(readOutputJournal(f.root, f.id).through).toBe(through);
  expect(fold(f).at(-1).text).toBe("retained segment output");
  expect(fs.existsSync(join(repaired.evidenceDirectory, `created-${name}.json`))).toBe(true);
  expect(oldRead(f.root, f.id).complete).toBe(false);
  expect(() => new OldWriter(f.root, f.id, "fixture-run")).toThrow();
  const next = new SessionOutputJournal(f.root, f.id, "fixture-run").append({
    type: "text_delta",
    text: "after missing repair",
  });
  expect(readOutputJournal(f.root, f.id, { after: through, through: next }).complete).toBe(true);
});
